export const getTotalA2ZQuestionsCount = (): number => STRIVERS_A2Z_QUESTIONS.length;

export const getQuestionsByStep = (stepNumber: number): StriverQuestion[] =>
  STRIVERS_A2Z_QUESTIONS.filter((q) => q.stepNumber === stepNumber);

export const getQuestionsBySubStep = (subStepId: string): StriverQuestion[] =>
  STRIVERS_A2Z_QUESTIONS.filter((q) => q.subStepId === subStepId);

export const getQuestionById = (id: string): StriverQuestion | undefined =>
  STRIVERS_A2Z_QUESTIONS.find((q) => q.id === id);

export const getA2ZDifficultyStats = () => {
  let easy = 0, medium = 0, hard = 0;
  for (const q of STRIVERS_A2Z_QUESTIONS) {
    if (q.difficulty === 'Easy') easy++;
    else if (q.difficulty === 'Medium') medium++;
    else if (q.difficulty === 'Hard') hard++;
  }
  return { total: STRIVERS_A2Z_QUESTIONS.length, easy, medium, hard };
};
